# Edge wrapper around an Apache-2.0 public Kaggriculture agent (notices in embedded source).
import base64 as _b64, zlib as _zlib
"""Market brain: decides how many premium units to SELL each turn.

Model
  * exact engine price curves (MARKET_PARAMS) and the town demand schedule
    (every unlocked shop consumes on step % 4 == 0, town center on step % 24 == 0);
  * opponent tracker: the opponent's harvests are visible on its tiles and its sales are
    visible as market-inventory changes (minus our sales, plus town consumption), so its
    hidden shed stock = harvested - sold;
  * allocator: every unit we hold is assigned greedily to the slot (now, or a future
    demand tick inside the horizon) where its marginal price is highest, given the
    forecast inventory path (opponent dumps its stock + visible yield soon, our own
    visible yield arrives soon, town demand drains). Only units assigned to "now" are sold.

Guards: never hold when that would leave less cash than the tape plans to spend in the
next day, never let the shed exceed `hold_cap`, and liquidate everything near the end.
"""
import math

MP = {
    "WHEAT": (25, 400, "sqrt", 0.80, "log", 0.20),
    "CARROT": (35, 450, "hinge", 1.00, "sqrt", 0.70),
    "TOMATO": (60, 200, "hinge", 0.40, "sqrt", 0.60),
    "STRAWBERRY": (120, 100, "sqrt", 0.70, "linear", 1.60),
    "MELON": (250, 300, "log", 0.20, "sq", 3.60),
    "EGG": (50, 332, "hinge", 0.40, "log", 0.20),
    "MILK": (160, 122, "sqrt", 0.60, "linear", 1.60),
    "WOOL": (200, 105, "log", 0.20, "sq", 3.20),
    "FERTILIZER": (100, 200, "linear", 0.40, "linear", 0.40),
}
I0 = 10000
SHOPS = {
    "BAKERY": ("EGG", "WHEAT"), "PIZZA_SHOP": ("MILK", "TOMATO", "WHEAT"),
    "BRUNCH_SPOT": ("EGG", "WHEAT", "STRAWBERRY"), "YARN_STORE": ("WOOL",),
    "ICE_CREAM_SHOP": ("STRAWBERRY", "MILK", "WHEAT"), "PET_CAFE": ("CARROT",),
    "SMOOTHIE_SHOP": ("STRAWBERRY", "MILK"), "FARMERS_MARKET": ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY"),
}
SOURCE = {"STRAWBERRY": "STRAWBERRY", "MELON": "MELON", "TOMATO": "TOMATO", "CARROT": "CARROT",
          "MILK": "COW", "WOOL": "SHEEP", "EGG": "GOOSE"}
SEED = {"WHEAT": 10, "CARROT": 20, "TOMATO": 50, "STRAWBERRY": 100, "MELON": 80}
ANIMAL = {"GOOSE": 300, "COW": 400, "SHEEP": 500}
LAND = (1000, 2000, 4000)


def _shape(f, x, T):
    x = max(0.0, x)
    if f == "linear":
        return x
    if f == "sq":
        return x * x
    if f == "sqrt":
        return math.sqrt(x)
    if f == "log":
        return math.log(1.0 + x)
    if f == "hinge":
        u = x / T
        return u + 8.0 * max(0.0, u - 1.0) ** 2
    return x


def price(item, inv):
    base, T, bf, bt, af, at = MP[item]
    if inv < I0:
        p = base + bt * base / _shape(bf, T, T) * _shape(bf, I0 - inv, T)
    else:
        p = base - at * base / _shape(af, T, T) * _shape(af, inv - I0, T)
    return max(1, int(round(p)))


def demand(item, step, shops):
    d = 0
    if step % 4 == 0:
        for s in shops:
            pr = SHOPS.get(s, ())
            if item in pr:
                d += 2 if len(pr) == 1 else 1
    if step % 24 == 0 and item != "FERTILIZER":
        d += 1
    return d


def _g(v, k, d=None):
    if isinstance(v, dict):
        return v.get(k, d)
    g = getattr(v, "get", None)
    return g(k, d) if callable(g) else getattr(v, k, d)


def _i(v, d=0):
    try:
        return int(v)
    except (TypeError, ValueError):
        return d


def _yields(tiles):
    """{(x,y): (product, yield_units)} for producing tiles."""
    out = {}
    for y, row in enumerate(tiles or []):
        for x, t in enumerate(row or []):
            if not isinstance(t, dict):
                continue
            src = t.get("animal") or t.get("crop")
            for prod, s in SOURCE.items():
                if s == src:
                    out[(x, y)] = (prod, _i(t.get("yield_units")))
    return out


class MarketBrain:
    def __init__(self, s):
        self.s = s
        self.items = tuple(s.get("brain_items", ("STRAWBERRY", "MILK", "WOOL", "MELON", "TOMATO")))
        self.prev_inv = None
        self.prev_opp = None
        self.my_sold_last = {}
        self.opp_harv = {}
        self.opp_sold = {}
        self.stats = {"held": 0, "extra": 0}

    # ---------- opponent tracking ----------
    def track(self, obs, step):
        mk = _g(obs, "market", {}) or {}
        inv = {k: _i(v) for k, v in (dict(_g(mk, "inventory", {}) or {})).items()}
        prices = dict(_g(mk, "prices", {}) or {})
        shops = list(_g(_g(obs, "town", {}) or {}, "unlocked_shops", []) or [])
        me = _i(_g(obs, "player", 0))
        opp_tiles = _g(_g(obs, "farms")[1 - me], "tiles")
        cur = _yields(opp_tiles)
        if self.prev_inv is not None:
            k = step - 1  # consumption of the step that just resolved
            for it in self.items:
                d = demand(it, k, shops)
                q = inv.get(it, 0) - self.prev_inv.get(it, 0) + d - self.my_sold_last.get(it, 0)
                if q > 0:
                    self.opp_sold[it] = self.opp_sold.get(it, 0) + q
            for pos, (prod, y0) in (self.prev_opp or {}).items():
                prod1, y1 = cur.get(pos, (prod, 0))
                if prod1 != prod:
                    y1 = 0
                if y1 < y0 and (y0 - y1) >= 1:
                    # a harvest empties the tile; slow 1-unit decay of old crops is not a harvest
                    if y1 == 0 or (y0 - y1) > 1:
                        self.opp_harv[prod] = self.opp_harv.get(prod, 0) + (y0 - y1)
        self.prev_inv = inv
        self.prev_opp = cur
        return inv, prices, shops, cur

    def opp_stock(self, it):
        return max(0, self.opp_harv.get(it, 0) - self.opp_sold.get(it, 0))

    # ---------- cash guard ----------
    def planned_spend(self, tape, step, horizon, prices):
        cost = 0.0
        hires = {}
        for t in range(step, min(step + horizon, len(tape or []))):
            a = tape[t] if isinstance(tape[t], dict) else {}
            day = t // 24
            for o in a.get("market") or []:
                if not o:
                    continue
                op = o[0]
                q = _i(o[2], 1) if len(o) > 2 else 1
                if op == "BUY_SEED":
                    cost += SEED.get(o[1], 50) * q
                elif op == "BUY_ANIMAL":
                    cost += ANIMAL.get(o[1], 400) * q
                elif op == "BUY_PRODUCT":
                    cost += (_i(prices.get(o[1], 30)) + 5) * q
                elif op == "HIRE":
                    n = hires.get(day, 0)
                    a_, b_ = 1, 1
                    for _ in range(n):
                        a_, b_ = b_, a_ + b_
                    cost += a_
                    hires[day] = n + 1
                elif op == "BUY_LAND":
                    cost += 4000
        return cost

    # ---------- allocation ----------
    def plan_item(self, it, step, inv_now, shops, my_stock, my_incoming, opp_now, opp_incoming, horizon):
        """Return how many of my_stock to sell now."""
        if my_stock <= 0:
            return 0
        end = min(718, step + horizon)
        slots = [step] + [t for t in range(step + 1, end + 1) if t % 4 == 0]
        if len(slots) == 1:
            return my_stock
        # baseline inventory path without our held units
        opp_lag = self.s.get("brain_opp_lag", 1)
        inc_lag = self.s.get("brain_inc_lag", 8)
        base = {}
        I = inv_now
        cum = 0
        extra = {}
        extra[min(step + opp_lag, end)] = extra.get(min(step + opp_lag, end), 0) + opp_now
        extra[min(step + inc_lag, end)] = extra.get(min(step + inc_lag, end), 0) + opp_incoming + my_incoming
        for t in range(step, end + 1):
            if t > step:
                I -= demand(it, t - 1, shops)
            I += extra.get(t, 0)
            base[t] = I
        assigned = {t: 0 for t in slots}
        disc = self.s.get("brain_disc", 0.0)
        for _ in range(my_stock):
            best, bv = None, -1.0
            for t in slots:
                # units already committed at or before t push inventory up at t
                above = sum(v for u, v in assigned.items() if u <= t)
                p = price(it, base[t] + above)
                if p <= 1:
                    v = 1.0
                else:
                    v = p * (1.0 - disc * (t - step) / 24.0)
                if v > bv + 1e-9:
                    best, bv = t, v
            assigned[best] += 1
        return assigned[step]

    def apply(self, obs, action, tape):
        step = _i(_g(obs, "step", 0))
        inv, prices, shops, opp_yield = self.track(obs, step)
        if not isinstance(action, dict):
            return action
        market = [list(o) for o in (action.get("market") or [])]
        priv = _g(obs, "private", {}) or {}
        shed = {k: _i(v) for k, v in dict(_g(priv, "shed", {}) or {}).items()}
        me = _i(_g(obs, "player", 0))
        farm = _g(obs, "farms")[me]
        money = float(_g(farm, "money", 0) or 0)
        my_yield = _yields(_g(farm, "tiles"))
        horizon = self.s.get("brain_horizon", 48)
        start = self.s.get("brain_start", 0)
        if step < start or step >= self.s.get("brain_end", 700):
            self.my_sold_last = self._sold(market, shed)
            return action
        tape_sell = {}
        for o in market:
            if o and o[0] == "SELL" and len(o) >= 3 and o[1] in self.items:
                tape_sell[o[1]] = tape_sell.get(o[1], 0) + max(0, _i(o[2]))
        want = {}
        for it in self.items:
            stock = shed.get(it, 0)
            if stock <= 0:
                continue
            my_inc = sum(y for p, y in my_yield.values() if p == it)
            opp_inc = sum(y for p, y in opp_yield.values() if p == it)
            q = self.plan_item(it, step, inv.get(it, I0), shops, stock, my_inc, self.opp_stock(it), opp_inc, horizon)
            if self.s.get("brain_only_more"):
                q = max(q, min(stock, tape_sell.get(it, 0)))
            want[it] = q
        # cash guard: selling less than the tape must not starve its purchases
        need = self.planned_spend(tape, step, self.s.get("brain_cash_h", 24), prices) + self.s.get("brain_cash_pad", 300)
        proj = money
        for it, q in want.items():
            proj += q * _i(prices.get(it, 1))
        for o in market:
            if o and o[0] == "SELL" and len(o) >= 3 and o[1] not in want:
                proj += min(_i(o[2]), shed.get(o[1], 0)) * _i(prices.get(o[1], 1))
        if proj < need:
            for it in sorted(want, key=lambda k: -_i(prices.get(k, 0))):
                gap = need - proj
                if gap <= 0:
                    break
                add = min(shed.get(it, 0) - want[it], max(0, tape_sell.get(it, 0) - want[it]) or shed.get(it, 0) - want[it])
                add = min(add, -(-int(gap) // max(1, _i(prices.get(it, 1)))))
                if add > 0:
                    want[it] += add
                    proj += add * _i(prices.get(it, 1))
        # shed guard
        cap = self.s.get("brain_hold_cap", 70)
        total_after = sum(shed.values()) - sum(want.values()) - sum(
            min(_i(o[2]), shed.get(o[1], 0)) for o in market if o and o[0] == "SELL" and len(o) >= 3 and o[1] not in want)
        if total_after > cap:
            over = total_after - cap
            for it in sorted(want, key=lambda k: _i(prices.get(k, 0))):
                add = min(over, shed.get(it, 0) - want[it])
                if add > 0:
                    want[it] += add
                    over -= add
                if over <= 0:
                    break
        # rewrite the market list
        new = []
        placed = set()
        for o in market:
            if o and o[0] == "SELL" and len(o) >= 3 and o[1] in self.items:
                it = o[1]
                if it in placed:
                    continue
                placed.add(it)
                # units the tape deposits and sells this same turn are not in the shed yet:
                # pass them through, the brain only controls stock already in the shed
                passthru = max(0, tape_sell.get(it, 0) - shed.get(it, 0))
                q = (want.get(it, 0) + passthru) if it in want else _i(o[2])
                if q > 0:
                    new.append(["SELL", it, q])
                continue
            new.append(o)
        for it, q in want.items():
            if it not in placed and q > 0:
                new.append(["SELL", it, q])
        for it in want:
            d = want[it] - min(tape_sell.get(it, 0), shed.get(it, 0))
            if d < 0:
                self.stats["held"] += -d
            else:
                self.stats["extra"] += d
        action = dict(action)
        action["market"] = new[:10]
        self.my_sold_last = self._sold(action["market"], shed)
        return action

    @staticmethod
    def _sold(market, shed):
        sh = dict(shed)
        out = {}
        for o in market or []:
            if o and o[0] == "SELL" and len(o) >= 3:
                q = min(max(0, _i(o[2])), sh.get(o[1], 0))
                sh[o[1]] = sh.get(o[1], 0) - q
                out[o[1]] = out.get(o[1], 0) + q
        return out


class Meter:
    """Crashed-market metering (what DSM does to us): when a premium item's price is below
    `meter_trigger` x base, sell only units whose marginal price stays >= `meter_floor` x base,
    i.e. roughly what the town just absorbed. Excess stays in the shed and is released at later
    demand ticks as the price recovers. Safety: if the shed would stay above `meter_shed_hi`,
    or on the final `meter_end` steps, the tape's sells go through unchanged."""

    def __init__(self, s):
        self.s = s
        self.items = tuple(s.get("meter_items", ("STRAWBERRY", "MILK", "WOOL", "MELON", "TOMATO")))
        self.cut = 0

    def apply(self, obs, action):
        if not isinstance(action, dict):
            return action
        step = _i(_g(obs, "step", 0))
        if step >= self.s.get("meter_end", 696):
            return action
        mk = _g(obs, "market", {}) or {}
        inv = {k: _i(v) for k, v in dict(_g(mk, "inventory", {}) or {}).items()}
        shed = {k: _i(v) for k, v in dict(_g(_g(obs, "private", {}) or {}, "shed", {}) or {}).items()}
        market = [list(o) for o in (action.get("market") or [])]
        trig = self.s.get("meter_trigger", 0.6)
        floor = self.s.get("meter_floor", 0.2)
        # shed after the tape's sells
        after = dict(shed)
        for o in market:
            if o and o[0] == "SELL" and len(o) >= 3:
                after[o[1]] = after.get(o[1], 0) - min(_i(o[2]), max(0, after.get(o[1], 0)))
        # free room = cap - shed after sells - goods in hands - goods still on our tiles (arrive today)
        priv = _g(obs, "private", {}) or {}
        carried = sum(_i(v) for inv_ in (_g(priv, "inventories", []) or []) for v in dict(inv_ or {}).values())
        me = _i(_g(obs, "player", 0))
        on_tiles = sum(y for _, y in _yields(_g(_g(obs, "farms")[me], "tiles")).values())
        room = (self.s.get("meter_shed_hi", 85) - sum(max(0, v) for v in after.values())
                - carried - on_tiles - self.s.get("meter_pad", 10))
        if self.s.get("meter_mode") == "spread":
            return self._spread(obs, action, market, shed, inv, step, trig)
        new = []
        for o in market:
            if o and o[0] == "SELL" and len(o) >= 3 and o[1] in self.items:
                it, q = o[1], _i(o[2])
                base = MP[it][0]
                I = inv.get(it, I0)
                if price(it, I) < trig * base:
                    k = 0
                    while k < q and price(it, I + k) >= floor * base:
                        k += 1
                    keep = min(q - k, max(0, room), shed.get(it, 0))
                    if keep > 0:
                        room -= keep
                        self.cut += keep
                        q -= keep
                if q > 0:
                    new.append(["SELL", it, q])
                continue
            new.append(o)
        action = dict(action)
        action["market"] = new
        return action

    def _spread(self, obs, action, market, shed, inv, step, trig):
        """DSM-style daily schedule for crashed items: the day's stock is released evenly over the
        demand ticks (hours in meter_ticks); everything left goes at meter_last_hour so the shed is
        empty before the night drop. Items above trig x base follow the tape (race)."""
        hour = step % 24
        day = step // 24
        if getattr(self, "_day", -1) != day:
            self._day, self._sold = day, {}
        ticks = tuple(self.s.get("meter_ticks", (1, 5, 9, 13, 17, 21)))
        last = self.s.get("meter_last_hour", 21)
        done = sum(1 for h in ticks if h <= hour)
        new = []
        for o in market:
            if o and o[0] == "SELL" and len(o) >= 3 and o[1] in self.items:
                it, q = o[1], _i(o[2])
                have = shed.get(it, 0)
                passthru = max(0, q - have)
                if price(it, inv.get(it, I0)) < trig * MP[it][0] and hour < last:
                    total = have + self._sold.get(it, 0)
                    target = -(-total * done // len(ticks)) if done else 0
                    allow = max(0, min(have, target - self._sold.get(it, 0)))
                    keep = max(0, min(q, have) - allow)
                    self.cut += keep
                    q = min(q, have) - keep + passthru
                if q > 0:
                    new.append(["SELL", it, q])
                    self._sold[it] = self._sold.get(it, 0) + min(q, have)
                continue
            new.append(o)
        # release held stock of crashed items on schedule even when the tape has no sell order
        listed = {o[1] for o in new if o and o[0] == "SELL" and len(o) >= 3}
        for it in self.items:
            have = shed.get(it, 0)
            if it in listed or have <= 0 or price(it, inv.get(it, I0)) >= trig * MP[it][0]:
                continue
            total = have + self._sold.get(it, 0)
            target = total if hour >= last else (-(-total * done // len(ticks)) if done else 0)
            q = max(0, min(have, target - self._sold.get(it, 0)))
            if q > 0:
                new.append(["SELL", it, q])
                self._sold[it] = self._sold.get(it, 0) + q
        action = dict(action)
        action["market"] = new[:10]
        return action


"""Edge layer: wraps an inner Kaggriculture agent and post-processes its market orders.

The inner agent is exec'd from its own source into a private namespace, so its module
state is isolated from ours. Every edge layer is wrapped in try/except: on any error we
return the inner action unchanged.

Layers (toggled by settings):
  lead_steps    : for premium goods, sell now the lots the inner tape plans to SELL in
                  steps t+2..t+lead_steps (the inner already leads by one step itself).
                  Against a copy of the same tape this sells our lot before the copy's
                  identical lot depresses the price. The inner never errors on selling
                  stock that is already gone: the engine just aborts that order.
  premium_first : move premium SELL orders to the front of the market list, highest
                  current price first (orders run in lockstep by index across players).
"""
import copy

PRODUCTS = ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON", "EGG", "MILK", "WOOL", "FERTILIZER")


def _get(v, k, d=None):
    if isinstance(v, dict):
        return v.get(k, d)
    g = getattr(v, "get", None)
    if callable(g):
        return g(k, d)
    return getattr(v, k, d)


def _i(v, d=0):
    try:
        return int(v)
    except (TypeError, ValueError):
        return d


class Edge:
    def __init__(self, inner_agent, settings, chassis_getter=None):
        self.inner = inner_agent
        self.s = settings
        self.chassis_getter = chassis_getter
        self.errors = 0

    def __call__(self, obs, config=None):
        action = self.inner(obs, config)
        try:
            out = self.post(obs, action)
        except Exception:
            self.errors += 1
            out = action
        sab = self.s.get("_sabotage_hires")
        sab = {int(k): v for k, v in sab.items()} if sab else None
        if sab and isinstance(out, dict) and _i(_get(obs, "day", 0)) in sab:
            m, k = [], 0
            for o in out.get("market") or []:
                if o and o[0] == "HIRE":
                    k += 1
                    if k > sab[_i(_get(obs, "day", 0))]:
                        continue
                m.append(o)
            out = dict(out, market=m)
            self._sab_removed = max(0, k - sab[_i(_get(obs, "day", 0))])
        if self.s.get("adapt"):
            try:
                sh = dict(_get(_get(obs, "private", {}) or {}, "shed", {}) or {})
                sold = {}
                for o in (out.get("market") or []) if isinstance(out, dict) else []:
                    if o and o[0] == "SELL" and len(o) >= 3:
                        q = min(max(0, _i(o[2])), sh.get(o[1], 0))
                        sh[o[1]] = sh.get(o[1], 0) - q
                        sold[o[1]] = sold.get(o[1], 0) + q
                self._my_sold = sold
            except Exception:
                self.errors += 1
        if self.s.get("brain"):
            try:
                if not hasattr(self, "_brain"):
                    self._brain = MarketBrain(self.s)
                out = self._brain.apply(obs, out, self._tape(obs))
            except Exception:
                self.errors += 1
        if self.s.get("courier"):
            try:
                if not hasattr(self, "_courier"):
                    self._courier = Courier(self.s)
                out = self._courier.apply(obs, out, self._tape(obs))
            except Exception:
                self.errors += 1
        if self.s.get("meter"):
            try:
                if not hasattr(self, "_meter"):
                    self._meter = Meter(self.s)
                out = self._meter.apply(obs, out)
            except Exception:
                self.errors += 1
        if self.s.get("rescue"):
            try:
                if not hasattr(self, "_rescue"):
                    self._rescue = Rescue(self.s)
                self._rescue.extra_hires = getattr(self, "_sab_removed", 0)
                self._sab_removed = 0
                out = self._rescue.apply(obs, copy.deepcopy(out))
            except Exception:
                self.errors += 1
        return out

    def _tape(self, obs):
        ch = self.chassis_getter() if self.chassis_getter else None
        if ch is None:
            return []
        st = ch.players.get(_i(_get(obs, "player", 0))) or {}
        return ch.routes.get(st.get("route")) or []

    def _tape_sells(self, obs, step_from, step_to):
        """Planned SELL qty per item in the inner's current route for [step_from, step_to]."""
        ch = self.chassis_getter() if self.chassis_getter else None
        if ch is None:
            return {}
        player = _i(_get(obs, "player", 0))
        st = ch.players.get(player) or {}
        route = st.get("route")
        tape = ch.routes.get(route)
        if not tape:
            return {}
        out = {}
        for t in range(step_from, min(step_to + 1, len(tape))):
            a = tape[t] if isinstance(tape[t], dict) else {}
            for o in a.get("market") or []:
                if o and o[0] == "SELL" and len(o) >= 3:
                    out[o[1]] = out.get(o[1], 0) + max(0, _i(o[2]))
        return out

    SHOPS = {"BAKERY": ("EGG", "WHEAT"), "PIZZA_SHOP": ("MILK", "TOMATO", "WHEAT"),
             "BRUNCH_SPOT": ("EGG", "WHEAT", "STRAWBERRY"), "YARN_STORE": ("WOOL",),
             "ICE_CREAM_SHOP": ("STRAWBERRY", "MILK", "WHEAT"), "PET_CAFE": ("CARROT",),
             "SMOOTHIE_SHOP": ("STRAWBERRY", "MILK"), "FARMERS_MARKET": ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY")}

    def _tape_lots(self, obs, item, a, b):
        ch = self.chassis_getter() if self.chassis_getter else None
        if ch is None:
            return {}
        st = ch.players.get(_i(_get(obs, "player", 0))) or {}
        tape = ch.routes.get(st.get("route"))
        out = {}
        for t in range(a, min(b + 1, len(tape or []))):
            x = tape[t] if isinstance(tape[t], dict) else {}
            q = sum(max(0, _i(o[2])) for o in x.get("market") or [] if o and o[0] == "SELL" and len(o) >= 3 and o[1] == item)
            if q:
                out[t] = q
        return out

    def _rival_leads(self, obs, step):
        """Infer the rival's premium sells from public market inventory (delta + town consumption - ours),
        match each against our own tape (a same-family rival runs the same tape) and vote on the rival's lead.
        Returns {item: lead to use} once there is evidence that the rival sells ahead of us."""
        mk = _get(obs, "market", {}) or {}
        inv = dict(_get(mk, "inventory", {}) or {})
        shops = list(_get(_get(obs, "town", {}) or {}, "unlocked_shops", []) or [])
        prev = getattr(self, "_prev_inv", None)
        self._prev_inv = inv
        votes = self.__dict__.setdefault("_votes", {})
        items = self.s.get("premium_items", ())
        if prev is not None and step >= 1:
            k = step - 1
            mine = getattr(self, "_my_sold", {}) or {}
            for it in items:
                cons = 0
                if k % 4 == 0:
                    for sh in shops:
                        pr = self.SHOPS.get(sh, ())
                        if it in pr:
                            cons += 2 if len(pr) == 1 else 1
                if k % 24 == 0:
                    cons += 1
                rq = _i(inv.get(it, 0)) - _i(prev.get(it, 0)) + cons - mine.get(it, 0)
                if rq <= 0:
                    continue
                lots = self._tape_lots(obs, it, k + 1, k + self.s.get("adapt_max", 48))
                for t, q in lots.items():
                    if q == rq:
                        j = t - k
                        v = votes.setdefault(it, {})
                        v[j] = v.get(j, 0) + 1
        out = {}
        L = self.s.get("lead_steps", 0)
        cap = self.s.get("adapt_max", 48)
        allv = {}
        for it in items:
            for j, c in (votes.get(it) or {}).items():
                allv[j] = allv.get(j, 0) + c
        if sum(allv.values()) >= self.s.get("adapt_min_votes", 4):
            best = max(allv, key=lambda j: (allv[j], -j))
            want = min(cap, max(L, best + self.s.get("adapt_margin", 2)))
            for it in items:
                out[it] = want
            if self.s.get("adapt_log") and step % 24 == 0:
                with open(self.s["adapt_log"], "a") as f:
                    f.write("%d %s %d" % (step, sorted(allv.items(), key=lambda x: -x[1])[:4], want) + chr(10))
        return out

    def post(self, obs, action):
        if not isinstance(action, dict):
            return action
        action = copy.deepcopy(action)
        market = [list(o) for o in (action.get("market") or [])]
        prices = dict(_get(_get(obs, "market", {}) or {}, "prices", {}) or {})
        shed = dict(_get(_get(obs, "private", {}) or {}, "shed", {}) or {})
        step = _i(_get(obs, "step", 0))
        items = self.s.get("premium_items", ())
        L = self.s.get("lead_steps", 0)
        lead_of = {}
        if self.s.get("adapt"):
            try:
                lead_of = self._rival_leads(obs, step)
            except Exception:
                self.errors += 1
        if L >= 2 and step < 718:
            future = self._tape_sells(obs, step + 2, step + max([L] + list(lead_of.values())))
            if lead_of:
                future = {it: self._tape_sells(obs, step + 2, step + lead_of.get(it, L)).get(it, 0) for it in items}
            selling = {}
            for o in market:
                if o and o[0] == "SELL" and len(o) >= 3:
                    selling[o[1]] = selling.get(o[1], 0) + max(0, _i(o[2]))
            for item in items:
                want = future.get(item, 0)
                if want <= 0 or _i(prices.get(item, 0)) < self.s.get("min_price", 2):
                    continue
                avail = max(0, _i(shed.get(item, 0)) - selling.get(item, 0))
                qty = min(avail, want)
                if qty <= 0:
                    continue
                merged = False
                for o in market:
                    if o and o[0] == "SELL" and o[1] == item:
                        o[2] = _i(o[2]) + qty
                        merged = True
                        break
                if not merged:
                    market.append(["SELL", item, qty])
        if self.s.get("premium_first"):
            is_p = lambda o: bool(o) and o[0] == "SELL" and len(o) >= 3 and o[1] in items
            prem = sorted([o for o in market if is_p(o)], key=lambda o: -_i(prices.get(o[1], 0)))
            market = prem + [o for o in market if not is_p(o)]
        op = self.s.get("opening")
        if op and step == 0:
            rest = [o for o in market if not (o and o[0] in ("BUY_PRODUCT", "SELL") and len(o) > 1 and o[1] == "WHEAT")]
            market = [list(o) for o in op] + rest
        action["market"] = market[:10]
        return action


ACCESS = ((4, 4), (5, 4), (4, 5), (5, 5))
STEP = {"NORTH": (0, -1), "SOUTH": (0, 1), "EAST": (1, 0), "WEST": (-1, 0)}


def _d(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def _toward(p, q):
    if p[0] < q[0]:
        return ["EAST"]
    if p[0] > q[0]:
        return ["WEST"]
    if p[1] < q[1]:
        return ["SOUTH"]
    if p[1] > q[1]:
        return ["NORTH"]
    return None


class Rescue:
    """Last-resort guard: an animal that is unfed with consecutive_unfed>=1 escapes tonight, a
    plant unwatered with consecutive_unwatered>=1 withers tonight. The inner tape assumes all its
    hires succeed; when one fails (cash ~$0 on day 1) nobody feeds that animal. Free (PASSing)
    units are sent to feed/water; late in the day a busy unit is taken for an animal."""

    def __init__(self, s):
        self.s = s
        self.day = -1
        self.jobs = {}  # unit index -> (x, y)

    def apply(self, obs, action):
        if not isinstance(action, dict):
            return action
        hour = _i(_get(obs, "hour", 0))
        day = _i(_get(obs, "day", 0))
        if day != self.day:
            self.day, self.jobs = day, {}
        left = 24 - hour  # actions still to come today, including this one
        me = _i(_get(obs, "player", 0))
        farm = _get(obs, "farms")[me]
        if _i(_get(farm, "hires_today", 0)) < getattr(self, "hire_req", 0) and getattr(self, "hire_day", -1) == day:
            self.short_day = day
        if getattr(self, "hire_day", -1) != day:
            self.hire_day, self.hire_req = day, 0
        self.hire_req += sum(1 for o in (action.get("market") or []) if o and o[0] == "HIRE") + getattr(self, "extra_hires", 0)
        tiles = _get(farm, "tiles")
        priv = _get(obs, "private", {}) or {}
        shed = dict(_get(priv, "shed", {}) or {})
        invs = [dict(x or {}) for x in (_get(priv, "inventories", []) or [])]
        pos = [tuple(_get(farm, "farmer"))] + [tuple(h) for h in (_get(farm, "hands", []) or [])]
        if self.s.get("rescue_only_short", True) and getattr(self, "short_day", -1) != day:
            self.jobs = {}
            return action
        acts = [action.get("farmer")] + list(action.get("hands") or [])
        acts += [["PASS"]] * (len(pos) - len(acts))
        acts = acts[:len(pos)]

        animals, plants = [], []
        for y, row in enumerate(tiles):
            for x, t in enumerate(row):
                if not isinstance(t, dict):
                    continue
                if t.get("animal") and not t.get("fed_today") and _i(t.get("consecutive_unfed")) >= 1:
                    animals.append((x, y))
                elif (t.get("kind") == "PLANT" and not t.get("watered_today") and _i(t.get("consecutive_unwatered")) >= 1
                      and _i(t.get("planted_day"), day) < day):
                    plants.append((x, y))
        if not animals and not plants:
            self.jobs = {}
            return action
        a_hour = self.s.get("rescue_hour", 12)
        p_hour = self.s.get("rescue_plant_hour", 99)
        if hour < min(a_hour, p_hour):
            return action
        risk_a = set(animals) if hour >= a_hour and day <= self.s.get("rescue_last_day", 20) else set()
        risk_p = set(plants) if hour >= p_hour and day <= self.s.get("rescue_plant_last_day", 19) else set()
        if not risk_a and not risk_p:
            self.jobs = {}
            return action
        # drop finished jobs
        self.jobs = {u: g for u, g in self.jobs.items() if u < len(pos) and (g in risk_a or g in risk_p)}

        def idle(u):
            a = acts[u]
            return (not a) or a[0] == "PASS"

        wheat_units = sum(inv.get("WHEAT", 0) for inv in invs)
        shed_wheat = shed.get("WHEAT", 0)

        def need(u, g):
            p = pos[u]
            if g in risk_p:
                return _d(p, g) + 1
            if invs[u].get("WHEAT", 0) > 0 if u < len(invs) else False:
                return _d(p, g) + 1
            acc = min(ACCESS, key=lambda a: _d(p, a) + _d(a, g))
            return _d(p, acc) + 1 + _d(acc, g) + 1

        taken = set(self.jobs.values())
        targets = [g for g in sorted(risk_a) if g not in taken] + [g for g in sorted(risk_p) if g not in taken]
        for g in targets:
            is_animal = g in risk_a
            best = None
            for u in range(len(pos)):
                if u in self.jobs:
                    continue
                n = need(u, g)
                if n > left:
                    continue
                busy = not idle(u)
                if busy and not (is_animal and left <= n + self.s.get("rescue_slack", 3)):
                    continue
                key = (busy, n)
                if best is None or key < best[0]:
                    best = (key, u)
            if best is not None:
                self.jobs[best[1]] = g

        need_wheat = 0
        for u, g in self.jobs.items():
            if g not in risk_a:
                continue
            p = pos[u]
            inv = invs[u] if u < len(invs) else {}
            if inv.get("WHEAT", 0) > 0:
                a = ["FEED"] if p == g else _toward(p, g)
            elif p in ACCESS:
                if shed_wheat > 0:
                    k = max(1, min(shed_wheat, len([h for v, h in self.jobs.items() if h in risk_a])))
                    a = ["PICKUP", "WHEAT", k]
                    shed_wheat -= k
                else:
                    a = ["PASS"]
                    need_wheat += 1
            else:
                acc = min(ACCESS, key=lambda q: _d(p, q) + _d(q, g))
                a = _toward(p, acc)
                if shed_wheat <= 0:
                    need_wheat += 1
                else:
                    shed_wheat -= 1
            acts[u] = a or ["PASS"]
        for u, g in self.jobs.items():
            if g in risk_p:
                p = pos[u]
                acts[u] = ["WATER"] if p == g else (_toward(p, g) or ["PASS"])

        if need_wheat > 0:
            market = [list(o) for o in (action.get("market") or [])]
            buying = sum(_i(o[2]) for o in market if o and o[0] == "BUY_PRODUCT" and len(o) >= 3 and o[1] == "WHEAT")
            want = need_wheat - buying
            if want > 0:
                prices = dict(_get(_get(obs, "market", {}) or {}, "prices", {}) or {})
                wp = _i(prices.get("WHEAT", 25)) + 3
                money = float(_get(farm, "money", 0) or 0)
                pre = []
                short = want * wp - money
                if short > 0:
                    for item in sorted((k for k, v in shed.items() if v > 0 and k in PRODUCTS and k != "WHEAT"),
                                       key=lambda k: -_i(prices.get(k, 0))):
                        pr = max(1, _i(prices.get(item, 1)))
                        q = min(shed[item], -(-int(short) // pr))
                        pre.append(["SELL", item, q])
                        short -= q * pr
                        if short <= 0:
                            break
                market = pre + [["BUY_PRODUCT", "WHEAT", want]] + market
                action["market"] = market[:10]
        action["farmer"] = acts[0]
        if len(pos) > 1:
            action["hands"] = acts[1:]
        return action


class Courier:
    """Detour courier: a tape worker carrying premium goods whose tape has a stretch of only
    moves/PASS long enough to walk to a shed-access tile, PLACE each premium item, and walk to the
    exact tile the tape would have reached at the end of that stretch, does so. Positions and all
    non-idle tape commands are unchanged, so the tape stays in sync; the goods reach the shed hours
    before the nightly auto-drop and can be sold the same day."""

    IDLE = ("PASS", "NORTH", "SOUTH", "EAST", "WEST")

    def __init__(self, s):
        self.s = s
        self.items = tuple(s.get("courier_items", ("STRAWBERRY", "MILK", "WOOL", "MELON", "TOMATO", "CARROT", "EGG")))
        self.plans = {}
        self.trips = 0
        self.units = 0

    @staticmethod
    def _move(p, c):
        d = STEP.get(c[0]) if c else None
        if not d:
            return p
        return (min(9, max(0, p[0] + d[0])), min(9, max(0, p[1] + d[1])))

    @staticmethod
    def _walk(p, q):
        out = []
        while p != q:
            c = _toward(p, q)
            out.append(c)
            p = Courier._move(p, c)
        return out

    def apply(self, obs, action, tape):
        if not isinstance(action, dict) or not tape:
            return action
        step = _i(_get(obs, "step", 0))
        hour = step % 24
        day = step // 24
        if getattr(self, "_day", -1) != day:
            self._day, self.plans = day, {}
        if step >= 717 or hour < self.s.get("courier_from", 1) or hour > self.s.get("courier_to", 20):
            return action
        me = _i(_get(obs, "player", 0))
        farm = _get(obs, "farms")[me]
        pos = [tuple(_get(farm, "farmer"))] + [tuple(h) for h in (_get(farm, "hands", []) or [])]
        invs = [dict(x or {}) for x in (_get(_get(obs, "private", {}) or {}, "inventories", []) or [])]
        cmds = [action.get("farmer") or ["PASS"]] + list(action.get("hands") or [])
        cmds += [["PASS"]] * (len(pos) - len(cmds))
        end = day * 24 + 23
        a0 = tape[step] if step < len(tape) and isinstance(tape[step], dict) else {}
        crew = 1 + len(a0.get("hands") or [])
        changed = False
        for u, p in enumerate(pos[:crew]):
            plan = self.plans.get(u)
            if plan is not None:
                k = step - plan["t0"]
                if 0 <= k < len(plan["cmds"]):
                    cmds[u] = plan["cmds"][k]
                    changed = True
                continue
            cargo = [it for it in self.items if invs[u].get(it, 0) > 0] if u < len(invs) else []
            if len(cargo) == 0 or sum(invs[u].get(it, 0) for it in cargo) < self.s.get("courier_min", 3):
                continue
            if not cmds[u] or cmds[u][0] not in self.IDLE:
                continue
            # idle stretch in the tape starting now; tape position at each step of it
            q = p
            window = []
            for t in range(step, end):
                a = tape[t] if t < len(tape) and isinstance(tape[t], dict) else {}
                units = [a.get("farmer") or ["PASS"]] + list(a.get("hands") or [])
                c = cmds[u] if t == step else (units[u] if u < len(units) else ["PASS"])
                if not c or c[0] not in self.IDLE:
                    break
                q = self._move(q, c)
                window.append(q)
            best = None
            for L in range(1, len(window) + 1):
                target = window[L - 1]
                acc = min(ACCESS, key=lambda a: _d(p, a) + _d(a, target))
                need = _d(p, acc) + len(cargo) + _d(acc, target)
                if need <= L:
                    best = (L, acc, target)
                    break
            if best is None:
                continue
            L, acc, target = best
            route = self._walk(p, acc) + [["PLACE", it, invs[u][it]] for it in cargo]
            route += self._walk(acc, target)
            route += [["PASS"]] * (L - len(route))
            self.plans[u] = {"t0": step, "cmds": route}
            self.trips += 1
            self.units += sum(invs[u][it] for it in cargo)
            cmds[u] = route[0]
            changed = True
        if changed:
            action = dict(action)
            action["farmer"] = cmds[0]
            action["hands"] = cmds[1:]
        return action

