_EDGE = Edge(_INNER_NS['agent'], {'premium_items': ['MELON', 'WOOL', 'MILK', 'STRAWBERRY', 'TOMATO', 'CARROT', 'EGG'], 'lead_steps': 48, 'premium_first': False, 'opening': [['BUY_PRODUCT', 'WHEAT', 10], ['SELL', 'WHEAT', 10], ['BUY_PRODUCT', 'WHEAT', 5]], 'rescue': True, 'meter': True, 'meter_mode': 'spread', 'meter_trigger': 0.3, 'courier': True}, _chassis)

